#include "traffic.hpp"
#include <algorithm>
#include <cmath>
namespace echodrive {
TrafficSystem::TrafficSystem(){reset(1);}
void TrafficSystem::reset(int streetId){street_=streetId;tick_=0;vehicles_.clear();const char* types[]={"سيدان","حافلة","شاحنة","دراجة","سيارة أجرة","شرطة"};for(int i=0;i<6;i++){TrafficVehicle v{i+1,types[(i+streetId)%6],18.0+i*13.0,(i%3-1)*1.7,35.0+(i*9)%45,i==5,TrafficState::Cruising,i%3,0.7+(i%4)*0.25};vehicles_.push_back(v);}}
void TrafficSystem::tick(double playerSpeed,bool automatic){++tick_;for(auto&v:vehicles_){const double gap=v.distance;const bool tooClose=gap<18.0;const bool emergencyAhead=v.emergency&&gap<45.0;const double target=emergencyAhead?std::min(105.0,v.speed+18.0):tooClose?std::max(10.0,playerSpeed-8.0):std::min(95.0,45.0+v.id*7.0);const double acceleration=std::clamp((target-v.speed)*0.06,-3.0,2.0);v.speed=std::max(0.0,v.speed+acceleration);v.distance-=std::max(-2.0,(v.speed-playerSpeed)*0.02);if(tooClose){v.state=automatic?TrafficState::Following:TrafficState::Yielding;if(automatic&&v.lane!=1){v.state=TrafficState::ChangingLane;v.lane=(v.lane+1)%3;v.lateral+=(v.lane-1)*0.08;}}else if(emergencyAhead)v.state=TrafficState::Emergency;else{v.state=(tick_+v.id)%37==0?TrafficState::ChangingLane:TrafficState::Cruising;if(v.state==TrafficState::ChangingLane)v.lane=(v.lane+1)%3;}v.lateral+=std::sin((tick_+v.id*17)*0.025)*0.02;if(v.distance<4){v.distance=75+(v.id*11)%35;v.state=TrafficState::Cruising;}}}
std::string TrafficSystem::nearestAlert(bool ar)const{const TrafficVehicle* n=nullptr;for(const auto&v:vehicles_)if(!n||v.distance<n->distance)n=&v;if(!n)return ar?"الطريق خالٍ":"Road is clear";if(n->emergency&&n->distance<45)return ar?"مركبة طوارئ تقترب، افسح المسار":"Emergency vehicle approaching, yield";if(n->distance<12)return ar?"تحذير، "+n->type+" قريبة جدًا أمامك":"Warning, a vehicle is very close ahead";if(n->distance<30)return ar?"مركبة "+n->type+" أمامك على بعد "+std::to_string((int)n->distance)+" متر":"A vehicle is ahead, "+std::to_string((int)n->distance)+" meters";return ar?"حركة المرور طبيعية":"Traffic is normal";}
std::string TrafficSystem::diagnostics(bool ar)const{int changing=0,emergency=0,following=0;for(const auto&v:vehicles_){changing+=v.state==TrafficState::ChangingLane;emergency+=v.state==TrafficState::Emergency;following+=v.state==TrafficState::Following;}return ar?"ذكاء المرور: "+std::to_string(vehicles_.size())+" مركبات، "+std::to_string(changing)+" تغييرات حارة، "+std::to_string(following)+" متابعة مسافة، "+std::to_string(emergency)+" طوارئ":"Traffic AI: "+std::to_string(vehicles_.size())+" vehicles, "+std::to_string(changing)+" lane changes, "+std::to_string(following)+" following states, "+std::to_string(emergency)+" emergencies";}
}
